def poser_categorie_ajustement(apps, schema_editor):
    """La catégorie qui porte les corrections de solde, une par sens.

    Un ajustement n'est ni une recette ni une charge : il mérite sa propre
    ligne, visible et modifiable par la suite depuis l'écran des catégories.
    """
    TransactionCategory = apps.get_model('core', 'TransactionCategory')
    for direction in ('IN', 'OUT'):
        TransactionCategory.objects.get_or_create(
            name='Ajustements de solde', direction=direction,
            defaults={'active': True})


def deposer_categorie_ajustement(apps, schema_editor):
    TransactionCategory = apps.get_model('core', 'TransactionCategory')
    TransactionCategory.objects.filter(name='Ajustements de solde').delete()


